with department_summary as (select dept_id, round(stddev(salary), 2) as stddev_salary, concat_ws(', ', sort_array(collect_set(job_title))) as job_title_values from employees where job_title in ('Engineer', 'Intern') group by dept_id) select d.budget, d.dept_name, ds.stddev_salary, ds.job_title_values from departments d inner join department_summary ds on d.id = ds.dept_id where ds.stddev_salary > 72 order by stddev_salary desc;
